import itertools
import random

def check_poly(n, d, P_coeffs):
    # P(x) = sum P_coeffs[i] * x^i
    def P(x):
        res = 0
        for i, c in enumerate(P_coeffs):
            res += c * (x**i)
        return res

    # Try k from 1 to n
    for k in range(1, n + 1):
        # Search for distinct a_1, ..., a_{k+1}
        # To keep the search space small, we use a limited range
        # But this is just a heuristic.
        search_range = range(-15, 16)
        for a_vals in itertools.combinations(search_range, k + 1):
            # Try all permutations of a_vals to see if any can be a_{k+1}
            # Actually, only the last one needs to be different.
            for i in range(k + 1):
                ak_plus_1 = a_vals[i]
                others = [a_vals[j] for j in range(k + 1) if j != i]
                if P(ak_plus_1) == sum(P(a) for a in others):
                    return True, k
    return False, None

def test_n(n, num_trials=10):
    for _ in range(num_trials):
        for d in range(1, n + 1):
            # P is monic of degree d
            # P(x) = x^d + c_{d-1}x^{d-1} + ... + c_0
            coeffs = [random.randint(-5, 5) for _ in range(d)] + [1]
            success, k = check_poly(n, d, coeffs)
            if not success:
                return False, d, coeffs
    return True, None, None

for n in range(1, 6):
    res, d, coeffs = test_n(n)
    print(f"n={n}: {res}, d={d}, coeffs={coeffs}")

import itertools

def check_poly_large(n, d, P_coeffs, search_limit=50):
    def P(x):
        res = 0
        for i, c in enumerate(P_coeffs):
            res += c * (x**i)
        return res

    for k in range(1, n + 1):
        # For k=1, we need P(a2) = P(a1)
        if k == 1:
            # Check if P is not injective
            # Since it's a polynomial, we can check a range
            vals = {P(x): x for x in range(-search_limit, search_limit + 1)}
            if len(vals) < 2 * search_limit + 1:
                # Found two x that give the same P(x)
                # To be sure they are distinct, we can find them
                seen = {}
                for x in range(-search_limit, search_limit + 1):
                    px = P(x)
                    if px in seen:
                        return True, 1
                    seen[px] = x

        # For k >= 2, we search for a_{k+1} and a_1, ..., a_k
        # This is more expensive.
        # Let's try to find if there exists a_1, ..., a_k such that sum P(a_i) is in the set of P values.
        p_vals = {P(x): x for x in range(-search_limit, search_limit + 1)}

        # Try k=2
        if k == 2:
            for a1 in range(-search_limit, search_limit + 1):
                for a2 in range(a1 + 1, search_limit + 1):
                    s = P(a1) + P(a2)
                    if s in p_vals:
                        a3 = p_vals[s]
                        if a3 != a1 and a3 != a2:
                            return True, 2

        # Try k=3
        if k == 3:
            # This is O(search_limit^3), might be slow
            for a1 in range(-search_limit, search_limit + 1):
                for a2 in range(a1 + 1, search_limit + 1):
                    for a3 in range(a2 + 1, search_limit + 1):
                        s = P(a1) + P(a2) + P(a3)
                        if s in p_vals:
                            a4 = p_vals[s]
                            if a4 != a1 and a4 != a2 and a4 != a3:
                                return True, 3
    return False, None

# Try to find a counterexample for n=3, d=3
for a in range(-10, 11):
    for b in range(-10, 11):
        for c in range(-10, 11):
            coeffs = [c, b, a, 1] # P(x) = x^3 + ax^2 + bx + c
            success, k = check_poly_large(3, 3, coeffs)
            if not success:
                print(f"Found counterexample: a={a}, b={b}, c={c}")
                # Let's double check with a larger search limit
                success_large, k_large = check_poly_large(3, 3, coeffs, search_limit=100)
                if not success_large:
                    print(f"Confirmed counterexample: a={a}, b={b}, c={c}")
                    # To be absolutely sure, we could try a much larger limit
                    # but let's see if we find any.
                else:
                    print(f"Not a counterexample after all: k={k_large}")

