def check_poly_fast_v2(n, d, P_coeffs, search_limit=200):
    def P(x):
        res = 0
        for i, c in enumerate(P_coeffs):
            res += c * (x**i)
        return res

    # Map from P(x) to x
    val_to_x = {}
    for x in range(-search_limit, search_limit + 1):
        val_to_x[P(x)] = x

    # k=1: P(a2) = P(a1)
    # If the size of the dictionary is less than the number of x's, it's not injective
    if len(val_to_x) < 2 * search_limit + 1:
        return True, 1

    # k=2: P(a3) = P(a1) + P(a2)
    # Use a list of values for iteration
    p_vals = list(val_to_x.keys())
    for i in range(len(p_vals)):
        for j in range(i + 1, len(p_vals)):
            s = p_vals[i] + p_vals[j]
            if s in val_to_x:
                a1 = val_to_x[p_vals[i]]
                a2 = val_to_x[p_vals[j]]
                a3 = val_to_x[s]
                if a3 != a1 and a3 != a2:
                    return True, 2

    # k=3: P(a4) = P(a1) + P(a2) + P(a3)
    # To optimize, we can precompute P(a1) + P(a2)
    sums_of_two = {}
    for i in range(len(p_vals)):
        for j in range(i + 1, len(p_vals)):
            s = p_vals[i] + p_vals[j]
            # Store the pair (a1, a2)
            sums_of_two[s] = (val_to_x[p_vals[i]], val_to_x[p_vals[j]])

    for a3_val in p_vals:
        for s2, (a1, a2) in sums_of_two.items():
            s3 = s2 + a3_val
            if s3 in val_to_x:
                a4 = val_to_x[s3]
                a3 = val_to_x[a3_val]
                if len({a1, a2, a3, a4}) == 4:
                    return True, 3

    return False, None

